<script lang="ts">
  import { onMount, tick, untrack } from 'svelte';
  import { fly } from 'svelte/transition';
  import { base } from '$app/paths';
  import { definition, purchaseReason, activePlayer } from '$lib/game/actions';
  import { setupSupply, type SetupState } from '$lib/game/setup';
  import type { GameCommand } from '$lib/backend/setup-repository';
  import CardFace from '../CardFace.svelte';
  import ResourceIcon from '../ResourceIcon.svelte';
  import GameButton from '../GameButton.svelte';
  import Portrait from './Portrait.svelte';
  let { game, uid, ready, status, error, command, retry, close }: { game: SetupState; uid: string; ready: boolean; status: string; error: string; command: (command: GameCommand) => Promise<void>; retry: () => void; close: () => void } = $props();
  let dialog = $state<HTMLDialogElement>(), detail = $state<HTMLDialogElement>();
  let page = $state(0), selected = $state('obol'), reduced = $state(true);
  const piles = $derived(setupSupply(game.playerCount).slice(page * 6, page * 6 + 6));
  const card = $derived(definition(selected));
  const reason = $derived(purchaseReason(game, uid, selected));
  const owned = $derived(game.decks[uid]);
  const latestGain = $derived(game.movements.findLast(move => move.uid === uid && move.kind === 'gain'));
  const initialGain = untrack(() => latestGain?.sequence);
  onMount(() => { dialog!.showModal(); const media=matchMedia('(prefers-reduced-motion: reduce)'); const update=()=>{reduced=media.matches;}; update(); media.addEventListener('change',update); return ()=>media.removeEventListener('change',update); });
  function selectPage(value: number) { page = value; selected = setupSupply(game.playerCount)[value * 6].id; }
  async function inspect() { await tick(); detail!.showModal(); }
  function gainFlight(node: Element) { return reduced || latestGain?.sequence === initialGain ? {duration:0} : fly(node,{x:-100,y:-90,duration:550}); }
</script>
<dialog bind:this={dialog} class="supply-scene" aria-label="Supply" oncancel={event=>{event.preventDefault();close();}} data-e2e-layout>
  <picture class="environment" aria-hidden="true"><source media="(max-aspect-ratio:3/4)" srcset={`${base}/assets/ui/table-mobile.webp`} /><img src={`${base}/assets/ui/table-desktop.webp`} alt="" /></picture>
  <button class="back" onclick={close}>‹ Table</button>
  <div class="player"><Portrait leader={game.leaders[uid]} name={game.players.find(player=>player.uid===uid)!.name} active={activePlayer(game)===uid}/></div>
  <div class="wallet" aria-label="Available resources"><ResourceIcon resource="coins" value={game.resources.coins}/><ResourceIcon resource="buys" value={game.resources.buys}/></div>
  <h1>Supply</h1>
  <nav class="tabs" aria-label="Supply pages">{#each ['Basics','Actions 1','Actions 2'] as label,index}<button aria-pressed={page===index} onclick={()=>selectPage(index)}>{label}</button>{/each}</nav>
  <section class="piles supply-piles" aria-label="Supply piles">{#each piles as pile}<button class:affordable={!purchaseReason(game,uid,pile.id)} aria-pressed={selected===pile.id} aria-label={`Select ${definition(pile.id).name}, ${game.supply[pile.id]} remaining`} onclick={()=>selected=pile.id}><CardFace card={definition(pile.id)} players={game.playerCount}/><span class="stock">{game.supply[pile.id]}</span></button>{/each}</section>
  <button class="selected-card" aria-label={`Inspect ${card.name}`} onclick={inspect}><CardFace {card} players={game.playerCount}/></button>
  <section class="purchase" aria-label="Purchase selected card"><h2>{card.name}</h2><div class="price"><ResourceIcon resource="coins" value={card.cost!}/><ResourceIcon resource="buys" value={1}/></div><GameButton primary disabled={!ready || !!reason} onclick={()=>command({type:'card/bought',cardId:selected})}>Buy {card.name}</GameButton><p class="reason" role="status">{reason || 'To your discard pile'}</p></section>
  <div class="destination" aria-label={`Your discard: ${owned.discard.length} cards`}>{#key latestGain?.sequence}{#if latestGain}<div class="gained" in:gainFlight|global><CardFace card={definition(latestGain.card!.cardId)} players={game.playerCount} copy={latestGain.card!.copy}/></div>{/if}{/key}<ResourceIcon resource="discard"/><span>Discard · {owned.discard.length}</span></div>
  <div class="near-hand" aria-label={`Your hand: ${owned.hand.length} cards`}>{#each owned.hand.slice(0,5) as instance}<div><CardFace card={definition(instance.cardId)} players={game.playerCount} copy={instance.copy}/></div>{/each}<img src={`${base}/assets/backs/back-deck.webp`} alt="Your deck"/></div>
  {#if error}<p class="error" role="alert">{error}</p>{/if}
  {#if status !== 'synced'}<div class="connection" role="status"><p>Connection lost. Your place is kept.</p><GameButton onclick={retry}>Try again</GameButton></div>{/if}
</dialog>
<dialog bind:this={detail} class="detail" aria-label={card.name} data-e2e-layout><h2>{card.name}</h2><div><CardFace {card} players={game.playerCount}/></div><GameButton onclick={()=>detail!.close()}>Back to supply</GameButton></dialog>
<style>
  dialog{color:#f5dfaf;}button{color:inherit;cursor:pointer;}button:focus-visible{outline:3px solid #ffdc84;outline-offset:3px;}.supply-scene{position:fixed;inset:0;width:100vw;height:100svh;max-width:none;max-height:none;margin:0;padding:0;border:0;background:#071321;overflow:hidden;isolation:isolate;}.environment{position:absolute;inset:0;z-index:-1;}.environment img{width:100%;height:100%;object-fit:cover;}.back{position:absolute;top:2%;left:2%;height:clamp(44px,5svh,96px);padding:8px 18px;border:1px solid #bc9956;background:#071321dd;border-radius:18px;font-size:clamp(16px,2svh,36px);}.player{position:absolute;top:2%;right:4%;width:12%;max-width:16svh;}.wallet{position:absolute;left:4%;top:11%;display:flex;gap:24px;--icon-size:clamp(24px,3svh,64px);}.supply-scene h1{position:absolute;top:3%;left:30%;width:40%;margin:0;text-align:center;font:600 clamp(30px,5svh,100px)/1 'Cormorant Garamond',serif;}.tabs{position:absolute;top:13%;left:29%;width:42%;display:flex;gap:8px;justify-content:center;}.tabs button{flex:1;min-height:44px;border:1px solid #c2a76b;background:#081521e8;font-size:clamp(14px,2svh,38px);border-radius:8px;padding:8px;}.tabs [aria-pressed=true]{background:#134c48;color:#ffe6af;box-shadow:0 0 12px #4ad9bd60;}.piles{position:absolute;top:23%;left:10%;width:80%;display:flex;gap:3%;justify-content:center;}.piles button{position:relative;width:13%;border:0;background:none;padding:0;filter:drop-shadow(4px 6px 2px #000);}.piles [aria-pressed=true]{filter:drop-shadow(0 0 10px #54d5bb);transform:translateY(-6px);}.stock{position:absolute;right:0;bottom:0;border:2px solid #c6a462;border-radius:50%;min-width:1.8em;min-height:1.8em;display:grid;place-items:center;background:#071321;font:bold clamp(14px,2svh,40px)/1 'Atkinson Hyperlegible',sans-serif;}.selected-card{position:absolute;left:25%;top:52%;width:15%;max-width:21svh;border:0;background:none;padding:0;}.purchase{position:absolute;left:44%;top:51%;width:30%;text-align:center;--control-height:clamp(50px,6svh,110px);--control-font:clamp(22px,3svh,50px);}.purchase h2{font:600 clamp(26px,4svh,70px)/1 'Cormorant Garamond',serif;margin:0 0 3svh;}.price{display:flex;justify-content:center;gap:3svh;margin:0 0 3svh;--icon-size:clamp(28px,4svh,72px);}.reason{font-size:clamp(14px,1.8svh,34px);margin:2svh 0 0;}.destination{position:absolute;right:5%;top:55%;width:12%;height:25%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;--icon-size:clamp(24px,3svh,64px);}.gained{width:65%;}.destination:has(.gained){--icon-size:clamp(18px,2svh,40px);}.destination span{font-size:clamp(14px,1.8svh,34px);background:#071321bb;white-space:nowrap;}.near-hand{position:absolute;bottom:1%;left:30%;width:40%;height:14%;display:flex;gap:2%;justify-content:center;}.near-hand>div{width:min(15%,10svh);aspect-ratio:5/7;align-self:flex-end;}.near-hand img{width:min(15%,10svh);height:auto;max-height:100%;object-fit:contain;align-self:flex-end;}.error{position:absolute;top:18%;left:20%;width:60%;margin:0;padding:8px;background:#552b20;text-align:center;}.connection{position:absolute;left:25%;top:40%;width:50%;background:#071321fa;border:2px solid #c9a357;border-radius:16px;padding:24px;text-align:center;}.detail{width:min(440px,92vw);max-height:95svh;border:2px solid #b59a59;border-radius:16px;background:#071321;text-align:center;padding:20px;--control-height:50px;--control-font:22px;}.detail>div{width:min(50vw,34svh);margin:0 auto 24px;}.detail h2{margin:0 0 18px;font:600 28px 'Cormorant Garamond',serif;}.detail::backdrop{background:#020811cc;backdrop-filter:blur(5px);}
  @media(max-aspect-ratio:3/4){.back{top:1%;left:3%;height:36px;font-size:13px;}.player{top:1%;right:4%;width:18%;}.wallet{top:8%;left:7%;gap:20px;--icon-size:20px;}.supply-scene h1{top:2%;left:34%;width:35%;font-size:30px;}.tabs{top:15%;left:4%;width:92%;gap:6px;}.tabs button{font-size:15px;padding:8px 4px;}.piles{top:23%;left:10%;width:80%;display:grid;grid-template-columns:repeat(3,1fr);gap:2svh 8%;}.piles button{width:100%;}.stock{font-size:13px;}.selected-card{left:8%;top:57%;width:29%;max-width:none;}.purchase{left:42%;top:57%;width:53%;--control-height:50px;--control-font:19px;}.purchase h2{font-size:24px;margin:0 0 2svh;}.price{gap:18px;margin-bottom:2svh;--icon-size:25px;}.reason{font-size:13px;margin-top:12px;}.destination{top:auto;bottom:12%;right:7%;width:44%;height:6%;flex-direction:row;--icon-size:19px;}.destination .gained{display:none;}.destination span{font-size:13px;}.near-hand{bottom:1%;left:10%;width:80%;height:10%;}.connection{left:5%;width:90%;top:40%;padding:18px;}.error{left:5%;width:90%;top:20%;font-size:12px;padding:4px;}}
</style>
